package com.fixmer.mared;
import java.util.*;import java.nio.file.*;import java.util.concurrent.*;
import com.fixmer.mared.commands.engine.*;import com.fixmer.mared.commands.expr.*;import com.fixmer.mared.commands.server_cmd.*;import com.fixmer.mared.technology.runtime.*;import com.fixmer.genesis.technology.runtime.*;
public class RuntimeChecks143{
 static int passed,failed;interface Work{void run()throws Exception;}static void ok(boolean b){if(!b)throw new AssertionError();}static void check(String n,Work w){try{w.run();passed++;System.out.println("PASS "+n);}catch(Throwable e){failed++;System.out.println("FAIL "+n+": "+e);}}
 static MaredScriptContext context(){return new MaredScriptContext(null,null,s->{});}static Object eval(MaredScriptContext c,String s){return MaredExpr.eval(s,c);}
 public static void main(String[]args)throws Exception{Path root=Files.createTempDirectory("mared-runtime143-");net.neoforged.fml.loading.FMLPaths.loadAbsolutePaths(root);
 check("map inherits caller values and isolates v/i",()->{var c=context();c.setVariable("offset",10L);c.setVariable("v",99L);c.setVariable("i",77L);ok(eval(c,"[1,2].map(\"$v + $offset\")").equals(List.of(11L,12L)));ok(c.getVariable("v").equals(99L)&&c.getVariable("i").equals(77L));});
 check("filter inherits caller threshold",()->{var c=context();c.setVariable("threshold",2L);ok(eval(c,"[1,2,3].filter(\"$v > $threshold\")").equals(List.of(3L)));});
 check("callbacks inherit user functions",()->{var c=context();c.setVariable("offset",10L);c.registerFunction("plus",List.of("n"),MaredScriptParser.parse("return $n + $offset"));ok(eval(c,"[1,2].map(\"plus($v)\")").equals(List.of(11L,12L)));ok(!c.hasVariable("n"));});
 check("nested callbacks preserve outer item",()->{var c=context();ok(eval(c,"[1,2].map(\"$v + [10].map(\\\"$v + 1\\\")[0]\")").equals(List.of(12L,13L)));});
 check("reduce inherits caller values and keeps accumulator private",()->{var c=context();c.setVariable("extra",1L);c.setVariable("acc",99L);ok(eval(c,"[1,2,3].reduce(\"acc\",\"item\",\"$acc + $item + $extra\")").equals(8L));ok(c.getVariable("acc").equals(99L)&&!c.hasVariable("item"));});
 check("callback recursion remains bounded",()->{var c=context();c.registerFunction("loop",List.of("v"),MaredScriptParser.parse("return [1].map(\"loop($v)\")"));try{eval(c,"[1].map(\"loop($v)\")");throw new AssertionError("Recursion accepted");}catch(IllegalArgumentException|IllegalStateException expected){var f=MaredScriptContext.class.getDeclaredField("callDepth");f.setAccessible(true);ok(f.getInt(c)==0);}});
 check("callback host capabilities and scope inherited",()->{var c=context();var scope=new ExecutionScope();c.setExecutionScope(scope);var seen=new ArrayList<Object>();c.setCapabilityHost(new com.fixmer.genesis.technology.links.InvocationCapabilities<MaredScriptContext>(){public boolean supports(String n){return n.equals("capture");}public Object call(String n,List<Object>a,MaredScriptContext child){ok(child.executionScope()==scope);seen.add(a.get(0));return a.get(0);}});eval(c,"[1,2].forEach(\"capture($v)\")");ok(seen.equals(List.of(1L,2L)));scope.close();});
 check("whole callback loop has cooperative budget",()->{var c=context();int[] calls={0};c.setCapabilityHost(new com.fixmer.genesis.technology.links.InvocationCapabilities<MaredScriptContext>(){public boolean supports(String n){return n.equals("slow");}public Object call(String n,List<Object>a,MaredScriptContext child){calls[0]++;try{Thread.sleep(2);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CancellationException();}return a.get(0);}});var input=new ArrayList<Object>();for(int n=0;n<1000;n++)input.add((long)n);long start=System.nanoTime();try{MaredMethods.call(input,"map",List.of("slow($v)"),c);throw new AssertionError("No callback budget");}catch(IllegalArgumentException expected){ok(calls[0]>0&&calls[0]<1000&&System.nanoTime()-start<2_000_000_000L);}});
 check("constructor failure restores parameters and depth",()->{var c=context();var scope=new ExecutionScope(1);var held=scope.own(ExecutionScope.Kind.EVENT,()->{});c.setExecutionScope(scope);c.setVariable("p",99L);c.registerFunction("f",List.of("p"),MaredScriptParser.parse("return $p"));for(int n=0;n<80;n++){try{c.callFunction("f",List.of(2L));throw new AssertionError("Resource limit ignored");}catch(IllegalStateException expected){}ok(c.getVariable("p").equals(99L));}var depth=MaredScriptContext.class.getDeclaredField("callDepth");depth.setAccessible(true);ok(depth.getInt(c)==0);held.close();ok(c.callFunction("f",List.of(3L)).equals(3L));ok(c.getVariable("p").equals(99L)&&scope.snapshot().resources()==0);scope.close();});
 check("constructor failure preserves absent parameter",()->{var c=context();var scope=new ExecutionScope(1);var held=scope.own(ExecutionScope.Kind.EVENT,()->{});c.setExecutionScope(scope);c.registerFunction("f",List.of("p"),MaredScriptParser.parse("return $p"));try{c.callFunction("f",List.of(2L));throw new AssertionError();}catch(IllegalStateException expected){}ok(!c.hasVariable("p"));held.close();scope.close();});
 check("client data provider reaches context and forks",()->{var c=context();int[] calls={0};c.setPlayerDataProvider143(()->{calls[0]++;return Map.of("self","LocalPlayer","x",17L,"hp",20L);});c.forceRefreshPlayerData();ok(c.getVariable("self").equals("LocalPlayer")&&c.getVariable("x").equals(17L));var fork=c.forkFor(null,null);fork.forceRefreshPlayerData();ok(fork.getVariable("hp").equals(20L)&&calls[0]==2);});
 check("client data refresh does not destroy unrelated variables",()->{var c=context();c.setVariable("counter",9L);c.setPlayerDataProvider143(()->Map.of("x",1L));c.forceRefreshPlayerData();ok(c.getVariable("counter").equals(9L));});
 check("submission reservation closes exactly once",()->{var r=new FileRun("tickets");var ticket=r.reserveSection143();ok(!r.readyForNextSection143());ticket.close();ticket.close();ok(r.readyForNextSection143());r.submissionDone();ok(r.snapshot().state()==FileRun.State.COMPLETED);});
 check("next foreground section waits for MR delay",()->{var r=new FileRun("sequence");var c=context();c.setExecutionScope(r.scope());var ticket=r.reserveSection143();var e=new MaredScriptExecutor(c,List.of(new MaredWaitCommand(1,"ticks")));r.attach(e);ticket.close();e.tick();ok(!r.readyForNextSection143());ok(r.snapshot().state()==FileRun.State.WAITING);e.tick();ok(!r.readyForNextSection143());e.tick();ok(r.readyForNextSection143());r.submissionDone();ok(r.snapshot().state()==FileRun.State.COMPLETED);});
 check("background resources do not block next section",()->{var r=new FileRun("background");var t=r.reserveSection143();var held=r.scope().own(ExecutionScope.Kind.EVENT,()->{});t.close();ok(r.readyForNextSection143());r.submissionDone();ok(r.snapshot().state()==FileRun.State.BACKGROUND);held.close();ok(r.snapshot().terminal());});
 check("stopped run refuses next section",()->{var r=new FileRun("cancel");r.requestStop();ok(!r.readyForNextSection143()&&r.reserveSection143()==null);});
 check("sequential MR executors retain file-local bindings",()->{var r=new FileRun("locals");var c=context();c.setExecutionScope(r.scope());for(String code:List.of("set counter = 42; func read() { return $counter }","set answer = call read()")){var t=r.reserveSection143();var e=new MaredScriptExecutor(c,MaredScriptParser.parse(code));r.attach(e);t.close();for(int n=0;n<50&&!e.isFinished();n++)e.tick();ok(e.failure()==null&&r.readyForNextSection143());}ok(c.getVariable("answer").equals(42L));r.submissionDone();ok(r.snapshot().state()==FileRun.State.COMPLETED);});
 check("owned host cancellation is not a failure",()->{var scope=new ExecutionScope();var e=new FrameExecutor(List.of(new FrameExecutor.Instruction(){public void execute(FrameExecutor ex){scope.close();throw new CancellationException("cancelled host");}}),ExecutionLimits.DEFAULT,scope);e.tick();ok(e.isFinished()&&e.failure()==null&&scope.snapshot().failure()==null&&scope.snapshot().resources()==0);});
 check("unrequested cancellation exception remains a failure",()->{var e=new FrameExecutor(List.of(new FrameExecutor.Instruction(){public void execute(FrameExecutor ex){throw new CancellationException("unexpected");}}),ExecutionLimits.DEFAULT,null);e.tick();ok(e.failure() instanceof CancellationException);});
 check("reduce rejects persistent and reserved binding names",()->{var c=context();for(String name:List.of("global.reducer143","self","world","$acc","a.b","")){try{MaredMethods.call(List.of(1L,2L),"reduce",List.of(name,"item","1"),c);throw new AssertionError("Accepted: "+name);}catch(IllegalArgumentException expected){}}ok(!c.hasVariable("global.reducer143"));});
 check("reduce rejects aliased accumulator and item",()->{try{MaredMethods.call(List.of(1L,2L),"reduce",List.of("item","item","$item + $item"),context());throw new AssertionError();}catch(IllegalArgumentException expected){}});
 System.out.println("Runtime143 passed="+passed+" failed="+failed);try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}if(failed>0)throw new AssertionError(failed+" checks failed");
 }
}
